import { Component, OnInit } from '@angular/core';
import { RecipeService } from './services/recipe.service';
import { AuthService } from './services/auth.service';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent implements OnInit {
  currentView: 'home' | 'detail' | 'upload' = 'home';
  selectedRecipeId: number | null = null;
  showLoginDialog = false;
  showRegisterDialog = false;

  constructor(
    public authService: AuthService,
    private recipeService: RecipeService
  ) {}

  ngOnInit() {
    this.authService.checkAuthStatus();
  }

  onRecipeClick(recipeId: number) {
    this.selectedRecipeId = recipeId;
    this.currentView = 'detail';
  }

  onBackToHome() {
    this.currentView = 'home';
    this.selectedRecipeId = null;
  }

  onUploadClick() {
    if (!this.authService.isAuthenticated()) {
      this.showLoginDialog = true;
    } else {
      this.currentView = 'upload';
    }
  }

  onRecipeUploaded() {
    this.currentView = 'home';
    // Rezepte neu laden
    window.location.reload();
  }

  openLogin() {
    this.showLoginDialog = true;
    this.showRegisterDialog = false;
  }

  openRegister() {
    this.showRegisterDialog = true;
    this.showLoginDialog = false;
  }

  closeDialogs() {
    this.showLoginDialog = false;
    this.showRegisterDialog = false;
  }

  onLoginSuccess() {
    this.closeDialogs();
    if (this.currentView === 'upload') {
      // Bleib auf Upload-Seite
    } else {
      window.location.reload();
    }
  }

  logout() {
    this.authService.logout();
    this.currentView = 'home';
  }
}
<div class="min-h-screen bg-gray-50">
  <!-- Header Component -->
  <app-header 
    [currentView]="currentView"
    (uploadClick)="onUploadClick()"
    (homeClick)="onBackToHome()"
    (loginClick)="openLogin()"
    (logoutClick)="logout()">
  </app-header>

  <!-- Main Content -->
  <main>
    <!-- Home View - Recipe Grid -->
    <app-recipe-grid 
      *ngIf="currentView === 'home'"
      (recipeClick)="onRecipeClick($event)">
    </app-recipe-grid>

    <!-- Detail View -->
    <app-recipe-detail 
      *ngIf="currentView === 'detail' && selectedRecipeId"
      [recipeId]="selectedRecipeId"
      (backClick)="onBackToHome()">
    </app-recipe-detail>

    <!-- Upload View -->
    <app-upload-recipe 
      *ngIf="currentView === 'upload'"
      (recipeUploaded)="onRecipeUploaded()"
      (cancelClick)="onBackToHome()">
    </app-upload-recipe>
  </main>

  <!-- Login Dialog -->
  <app-login-dialog
    *ngIf="showLoginDialog"
    (close)="closeDialogs()"
    (loginSuccess)="onLoginSuccess()"
    (switchToRegister)="openRegister()">
  </app-login-dialog>

  <!-- Register Dialog -->
  <app-register-dialog
    *ngIf="showRegisterDialog"
    (close)="closeDialogs()"
    (registerSuccess)="onLoginSuccess()"
    (switchToLogin)="openLogin()">
  </app-register-dialog>
</div>
